// Contracts for the Windows replacement helper generated by packaging/update.js.
// Static shape checks run everywhere; the end-to-end swap runs only on Windows
// (native proof lane: CI windows-2025). Fixture files only; no real executable,
// release, tag or upload is involved.
const assert = require('node:assert/strict'), fs = require('node:fs'), os = require('node:os'), path = require('node:path');
const { windowsHelperScript } = require('../packaging/update');

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ep-update-helper-'));
const staging = path.join(dir, '.update-test');
fs.mkdirSync(staging);
const exe = path.join(dir, 'educationperfected-fixture.cmd');
const staged = path.join(staging, 'educationperfected-fixture.cmd');
const backup = exe + '.backup';
const receipt = exe + '.update-result';
const script = windowsHelperScript({ executable: exe, staged, backup, version: '2026.1.5', receipt, staging });

// Static contract: wait-for-unlock, swap, version check, rollback, receipt, self-cleanup.
for (const fragment of ['move /y "%EXE%" "%BACKUP%"', 'move /y "%STAGED%" "%EXE%"', 'goto restore', '"%EXE%" version', 'echo ok %WANT%>"%RECEIPT%"', 'echo rollback version-check-failed>"%RECEIPT%"', 'echo rollback still-running>"%RECEIPT%"', 'del "%~f0"']) {
    assert.ok(script.includes(fragment), fragment);
}
assert.ok(script.includes('if %tries% geq 180'), 'bounded wait');
assert.ok(script.includes('\r\n'), 'cmd line endings');
// Paths with cmd metacharacters are refused instead of producing an injectable script.
assert.throws(() => windowsHelperScript({ executable: String.raw`C:\100% disk\ep.exe`, staged, backup, version: '2026.1.5', receipt, staging }), /% or !/);
assert.throws(() => windowsHelperScript({ executable: exe, staged, backup, version: '2026.1.5', receipt: String.raw`C:\a!b`, staging }), /% or !/);

if (process.platform !== 'win32') {
    console.log('Windows update helper: static script contracts passed; end-to-end swap skipped off Windows (runs in the windows-2025 CI lane).');
} else {
    // End-to-end on Windows: nothing holds the fixture open, so the helper swaps
    // immediately. The locked-file case (real running exe) is covered by the retry
    // loop's static contract and stays a documented limit of this proof.
    fixtureCmd(exe, '2026.0.0');
    fixtureCmd(staged, '2026.1.5');
    fs.mkdirSync(staging, { recursive: true });
    fs.writeFileSync(path.join(dir, 'apply-update.cmd'), script);
    const result = require('node:child_process').spawnSync(process.env.ComSpec || 'cmd.exe', ['/c', path.join(dir, 'apply-update.cmd')], { encoding: 'utf8', timeout: 120000 });
    assert.equal(result.status, 0, result.stderr);
    assert.equal(fs.readFileSync(receipt, 'utf8').trim(), 'ok 2026.1.5');
    assert.ok(fs.readFileSync(exe, 'utf8').includes('2026.1.5'), 'staged build swapped in');
    assert.ok(fs.readFileSync(backup, 'utf8').includes('2026.0.0'), 'previous bytes kept as backup');

    // Healthcheck failure path: staged build reports the wrong version; helper rolls back.
    fixtureCmd(exe, '2026.1.5');
    fixtureCmd(staged, '2026.9.9');
    fs.rmSync(receipt, { force: true });
    fs.mkdirSync(staging, { recursive: true });
    fs.writeFileSync(path.join(dir, 'apply-update-2.cmd'), windowsHelperScript({ executable: exe, staged, backup, version: '2026.2.0', receipt, staging }));
    const failed = require('node:child_process').spawnSync(process.env.ComSpec || 'cmd.exe', ['/c', path.join(dir, 'apply-update-2.cmd')], { encoding: 'utf8', timeout: 120000 });
    assert.equal(failed.status, 0, failed.stderr);
    assert.equal(fs.readFileSync(receipt, 'utf8').trim(), 'rollback version-check-failed');
    assert.ok(fs.readFileSync(exe, 'utf8').includes('2026.1.5'), 'previous build restored');
    console.log('Windows update helper: static contracts plus native swap, receipt and rollback passed on ' + process.platform + '.');
}

function fixtureCmd(file, version) {
    fs.writeFileSync(file, '@echo off\r\necho ' + version + '\r\n');
}

fs.rmSync(dir, { recursive: true, force: true });
